<?php $title='Métricas'; ?><div class="page-heading"><div><p class="eyebrow">Análisis de uso</p><h1>Métricas</h1><p>Estadísticas calculadas desde reproducciones registradas.</p></div></div><section class="panel mb-4"><form class="filter-bar" method="get"><div><label class="form-label" for="desde">Desde</label><input class="form-control" type="date" id="desde" name="desde" value="<?= e($from) ?>"></div><div><label class="form-label" for="hasta">Hasta</label><input class="form-control" type="date" id="hasta" name="hasta" value="<?= e($to) ?>"></div><button class="btn btn-dark align-self-end">Aplicar período</button></form></section><div class="row g-4 mb-4"><div class="col-md-4"><div class="stat-card"><span>Reproducciones del período</span><strong><?= number_format($total) ?></strong><small><?= e(date('d/m/Y',strtotime($from))) ?> — <?= e(date('d/m/Y',strtotime($to))) ?></small></div></div><div class="col-md-8"><section class="panel h-100"><div class="panel-title"><h2>Tendencia diaria</h2></div><?php $max=max(array_column($trend,'total')?:[1]); ?><div class="mini-chart"><?php foreach($trend as $day): ?><div class="mini-column" title="<?= e($day['fecha']) ?>: <?= $day['total'] ?>"><i style="height:<?= $max?(int)$day['total']/$max*100:0 ?>%"></i><small><?= e(date('d/m',strtotime($day['fecha']))) ?></small></div><?php endforeach; ?><?php if(!$trend): ?><p class="empty w-100">No hay reproducciones en este período.</p><?php endif; ?></div></section></div></div><div class="row g-4"><div class="col-lg-6"><section class="panel"><div class="panel-title"><h2>Audios más reproducidos</h2></div><ol class="rank-list"><?php foreach($top as $item): ?><li><a href="<?= url('/audios/'.$item['id_audio']) ?>"><?= e($item['titulo']) ?></a><strong><?= number_format($item['total']) ?></strong></li><?php endforeach; ?><?php if(!$top): ?><p class="empty">Sin datos en el período.</p><?php endif; ?></ol></section></div><div class="col-lg-6"><section class="panel"><div class="panel-title"><h2>Categorías con mayor uso</h2></div><?php $maxCat=max(array_column($categories,'total')?:[1]);foreach($categories as $item): ?><div class="bar-row"><span><?= e($item['nombre']) ?></span><div class="bar-track"><i style="width:<?= $maxCat?(int)$item['total']/$maxCat*100:0 ?>%"></i></div><strong><?= $item['total'] ?></strong></div><?php endforeach; ?><?php if(!$categories): ?><p class="empty">Sin datos en el período.</p><?php endif; ?></section></div><div class="col-12"><section class="panel"><div class="panel-title"><h2>Carga mensual</h2></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Mes</th><th>Archivos registrados</th></tr></thead><tbody><?php foreach($uploads as $item): ?><tr><td><?= e($item['mes']) ?></td><td><?= number_format($item['total']) ?></td></tr><?php endforeach; ?></tbody></table></div></section></div></div>

